{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林清语",
      "role": "protagonist",
      "identity": "古董鉴定师/文物修复师",
      "traits": ["冷静理智", "技术偏执", "嘴硬心软", "内心孤独", "渴望认可"],
      "overt_motivation": "用专业能力在古董行站稳脚跟，重新获得人生价值",
      "covert_motivation": "证明自己不是靠家世，而是靠真本事获得认可",
      "secret_fear": "害怕自己其实真的只是靠家世，没有真本事"
    },
    {
      "name": "顾行舟",
      "role": "deuteragonist",
      "identity": "资深古董鉴定师/拍卖行顾问",
      "traits": ["沉稳内敛", "专业严谨", "外冷内热", "原则性强", "洞察力敏锐"],
      "overt_motivation": "在古董行建立自己的鉴定机构",
      "covert_motivation": "寻找失踪的师父，查清当年文物走私案真相",
      "secret_fear": "害怕自己的判断失误导致珍贵文物流失或被毁"
    }
  ],
  "supporting_characters": [
    {
      "name": "顾母",
      "function": "阻碍",
      "identity": "豪门贵妇/顾行舟母亲",
      "description": "强势专断，认为儿子应该继承家族企业而非从事古董行业，多次试图阻挠顾行舟的事业"
    },
    {
      "name": "赵德全",
      "function": "助力",
      "identity": "故宫退休陶瓷修复师/林清语外公",
      "description": "林清语的外公，故宫退休陶瓷修复大师，传授她鉴定和修复技艺，但身体每况愈下"
    },
    {
      "name": "陈锋",
      "function": "阻碍",
      "identity": "古董商/前夫家法律顾问",
      "description": "前夫家的法律顾问，精通古董行规则漏洞，专门负责处理前夫家的资产纠纷，手段阴险"
    },
    {
      "name": "苏婉",
      "function": "反转点",
      "identity": "拍卖行女老板",
      "description": "表面是精明的商人，实则掌握着前夫家走私文物的证据，关键时刻会反水"
    },
    {
      "name": "周明",
      "function": "助力",
      "identity": "年轻鉴定师/顾行舟助手",
      "description": "顾行舟的年轻助手，虽然经验不足但勤奋好学，关键时刻提供技术支持"
    }
  ],
  "relationship_dynamics": "林清语与顾行舟初期是竞争关系（互相看不上对方的鉴定风格），中期因共同对抗前夫家的法律追讨而建立合作，后期在多次专业分歧和危机中逐渐产生信任和默契，最终成为势均力敌的伴侣。两人的关系转折点与案件进展紧密呼应：第一次合作鉴定→发现前夫家走私线索→共同对抗法律追讨→感情升温。"
}"}

