{"path": "outline.json", "content": "{
  "creative_intent": {
    "x_axis_mode": "B9",
    "y_axis_tags": ["Y8", "Y12"],
    "chemical_reaction": "↘",
    "emotional_baseline": "angsty",
    "word_count_target": 120000
  },
  "act_one": {
    "story_synopsis": "沈清辞离婚后分得一箱'破烂'，意外发现其中有价值八千万的永乐青花孤品。她决定不声张，带着这批古董重新在古董行立足。然而古董行水深，她很快遭遇设局、看走眼等挫折。前夫家得知消息后开始法律追讨，沈清辞在鉴定专业、商业谈判、法律攻防三条线上同时作战。她结识了古董商顾深，两人达成利益交换：顾深帮她处理纠纷，她帮顾深鉴定藏品。第一幕在沈清辞成功卖出第一件古董，却被前夫家发现并发出律师函时结束。",
    "chapter_synopses": [
      {
        "chapter_number": 1,
        "synopsis": "沈清辞离婚当天拿到一箱'破烂'，在整理时凭借外公三十年前的修复经验认出永乐青花孤品。她决定隐瞒真相，带着古董离开。前夫家的冷漠和轻视让她更加坚定要证明自己。她找到老陈询问市场行情，老陈警告她古董行的危险，但她执意要闯一闯。"
      },
      {
        "chapter_number": 2,
        "synopsis": "沈清辞开始在古玩市场摆摊，却因没有名气被冷落。她遇到第一个设局者——有人拿高仿品让她鉴定，差点看走眼。关键时刻顾深出现，指出破绽并解围。顾深看出沈清辞的专业能力，提出合作：他提供场地和客源，她负责鉴定，利润分成。沈清辞犹豫后答应。"
      },
      {
        "chapter_number": 3,
        "synopsis": "两人合作的第一单生意：鉴定一批民国瓷器。沈清辞凭借专业知识发现其中有赝品，但卖家强势施压。顾深用商业手段化解危机，沈清辞则用技术细节说服买家。交易成功，沈清辞赚到第一桶金。但前夫的律师突然出现，送达律师函要求归还'家族财产'。"
      }
    ],
    "turning_point": "沈清辞在成功卖出第一批古董后，收到前夫家的律师函，法律纠纷正式开始，她意识到这场战斗才刚刚开始。"
  },
  "act_two": {
    "story_synopsis": "法律纠纷升级，前夫家不仅要追讨古董，还动用关系封杀沈清辞。行业内开始流传她'盗窃家族财产'的谣言。沈清辞在一次重要拍卖中被林志远（前同事）当众质疑鉴定能力，陷入信任危机。顾深在关键时刻支持她，两人关系升温。沈清辞发现林志远被赵美娟收买，决定反击。她通过调查发现前夫家的藏品中有多件赝品，这成为反击的筹码。第二幕在沈清辞公开揭露前夫家藏品造假，引发行业震动时达到高潮。",
    "chapter_synopses": [
      {
        "chapter_number": 4,
        "synopsis": "前夫家通过媒体散布谣言，称沈清辞'盗窃'古董。拍卖行开始拒绝与她合作，老顾客纷纷避嫌。沈清辞陷入困境，但她没有退缩，开始暗中调查前夫家的藏品来源。顾深提供资源支持，两人在合作中逐渐了解彼此的过去。"
      },
      {
        "chapter_number": 5,
        "synopsis": "一场重要的古董拍卖会，沈清辞作为鉴定顾问参与。林志远突然质疑她对一件宋代汝窑的鉴定，引发争议。沈清辞据理力争，但因缺乏权威背书处于下风。关键时刻顾深拿出证据支持沈清辞，暂时化解危机。事后沈清辞发现林志远与赵美娟有秘密接触。"
      },
      {
        "chapter_number": 6,
        "synopsis": "沈清辞开始反击，她深入调查发现前夫家的'传家宝'中有多件是现代高仿品，包括赵美娟最引以为傲的一件明代宣德炉。她收集证据，准备在行业交流会上公开。同时，她与顾深的感情在共同战斗中升温，但两人都保持克制，不愿让感情影响判断。"
      },
      {
        "chapter_number": 7,
        "synopsis": "行业交流会上，沈清辞当众揭露前夫家藏品造假的证据，包括详细的技术分析和对比照片。现场一片哗然，赵美娟恼羞成怒。林志远试图辩解，但被沈清辞用专业数据驳倒。沈清辞一战成名，但也彻底得罪了前夫家和部分既得利益者。"
      }
    ],
    "turning_point": "沈清辞公开揭露前夫家藏品造假，虽然赢得了专业声誉，但也让自己陷入更危险的境地——前夫家开始动用非法手段报复。"
  },
  "act_three": {
    "story_synopsis": "前夫家开始动用非法手段：威胁老陈、破坏沈清辞的鉴定设备、甚至制造车祸。沈清辞在一次鉴定中因设备被做手脚差点看走眼，造成重大损失。顾深为保护她受伤，两人感情突破。沈清辞决定不再被动防守，主动出击。她联合老陈和其他被前夫家欺压的小商贩，收集赵美娟走私文物、洗钱的证据。最终在一场关键的法庭对决和拍卖会上，沈清辞不仅赢了官司，还让前夫家的丑闻公之于众。故事结尾，沈清辞成立了自己的鉴定事务所，与顾深成为平等的合作伙伴和恋人。",
    "chapter_synopses": [
      {
        "chapter_number": 8,
        "synopsis": "前夫家开始报复：老陈的摊位被砸，沈清辞的鉴定设备被做手脚。在一次重要鉴定中，沈清辞因设备故障差点误判一件赝品为真品，幸亏顾深及时发现。两人意识到必须主动出击，不能再被动防守。"
      },
